function readControlSettings(){try{const saved=JSON.parse(localStorage.getItem(SETTINGS_KEY));if(!saved)return;if(typeof saved.showArrivalHints==='boolean')showArrivalHints=saved.showArrivalHints;if(typeof saved.showKeyboardLabels==='boolean')showKeyboardLabels=saved.showKeyboardLabels;if(['filled','outline'].includes(saved.judgmentStyle))judgmentStyle=saved.judgmentStyle;if(Array.isArray(saved.bindings)&&saved.bindings.length===8&&new Set(saved.bindings).size===8&&saved.bindings.every(validBinding))bindingCodes=[...saved.bindings];if(EFFECT_PACKS.some(p=>p.id===saved.soundPack))soundPack=saved.soundPack;if(typeof saved.hitSound==='boolean')hitSoundEnabled=saved.hitSound;if(typeof saved.timingOffset==='number'&&Number.isFinite(saved.timingOffset))timingOffsetMs=Math.max(-250,Math.min(250,saved.timingOffset));if(typeof saved.musicVolume==='number'&&Number.isFinite(saved.musicVolume))musicVolume=Math.max(0,Math.min(1,saved.musicVolume));if(typeof saved.volume==='number'&&Number.isFinite(saved.volume))hitVolume=Math.max(0,Math.min(1,saved.volume))}catch{}}
