function initHitAudio(){sfxGain=ac.createGain();connectHitOutput(ac,sfxGain,audioBus);updateHitGain();for(const kind of ['kick','snare','hat','tom'])if(!drumBuffers.has(kind))drumBuffers.set(kind,buildDrumBuffer(kind))}
