function captureBinding(e){if(!settingsOpen)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(captureLane!==null){captureLane=null;renderBindingWheel();document.querySelector('#binding-status').textContent='已取消按鍵指定。'}else closeSettings();return}if(captureLane===null)return;if(e.code==='Tab')return;e.preventDefault();e.stopImmediatePropagation();if(e.repeat||e.isComposing||e.ctrlKey||e.metaKey||e.altKey||!validBinding(e.code)){document.querySelector('#binding-status').textContent='請使用英文字母、數字、方向鍵或標點鍵；空白鍵保留給暫停。';return}const lane=captureLane,other=draftBindings.indexOf(e.code),previous=draftBindings[lane];if(other!==-1&&other!==lane)draftBindings[other]=previous;draftBindings[lane]=e.code;captureLane=null;renderBindingWheel();document.querySelector('#binding-status').textContent=LANE_NAMES[lane]+' → '+keyLabel(e.code)+(other!==-1&&other!==lane?'；已與「'+LANE_NAMES[other]+'」交換。':'，按儲存套用。');document.querySelectorAll('#mapping-wheel .binding-key')[lane].focus()}
async function saveControlSettings(e){e.preventDefault();if(captureLane!==null){document.querySelector('#binding-status').textContent='請先完成按鍵指定，或按 Esc 取消指定。';return}const chosenProfiles=validateSymbolSounds(draftSymbolSounds,document.querySelector('#effect-pack').value),chosenPack=document.querySelector('#effect-pack').value,generation=settingsGeneration,saveButton=document.querySelector('.settings-save');saveButton.disabled=true;stopEffectPreview();try{if(ac)await Promise.all([loadEffectPack(ac,chosenPack),loadSymbolPacks(ac,chosenProfiles,chosenPack)])}catch{document.querySelector('#effect-status').textContent='無法載入這組音效，請重試或選另一組。';saveButton.disabled=false;return}saveButton.disabled=false;if(!settingsOpen||generation!==settingsGeneration)return;soundPack=chosenPack;symbolSounds=chosenProfiles;for(const id of [...held.keys()])release(id);bindingCodes=[...draftBindings];judgmentStyle=document.querySelector('#judgment-outline').checked?'outline':'filled';showArrivalHints=document.querySelector('#show-arrival-hints').checked;showKeyboardLabels=document.querySelector('#show-keyboard-labels').checked;hitSoundEnabled=document.querySelector('#hit-sound-enabled').checked;hitVolume=Number(document.querySelector('#hit-volume').value)/100;timingOffsetMs=Number(document.querySelector('#timing-offset').value);musicVolume=Number(document.querySelector('#music-volume').value)/100;updateMappingLabels();updateHitGain();if(musicGain)musicGain.gain.value=muted?0:musicVolume;let persisted=true;try{localStorage.setItem(SETTINGS_KEY,JSON.stringify({bindings:bindingCodes,judgmentStyle,showArrivalHints,showKeyboardLabels,hitSound:hitSoundEnabled,volume:hitVolume,timingOffset:timingOffsetMs,musicVolume,soundPack,soundProfileRevision:SOUND_PROFILE_REVISION,symbolSounds}))}catch{persisted=false}closeSettings();showToast(persisted?(mode==='paused'?'設定已儲存，按「繼續」返回':'設定已儲存'):'設定已套用；瀏覽器無法保存，重新整理後會恢復預設。')}
function initSettings(){readControlSettings();initSymbolSettings();initEffectOptions();updateMappingLabels();document.addEventListener('click',e=>{const b=e.target.closest('[data-open-settings]');if(b)openSettings(b)});addEventListener('keydown',captureBinding,true);document.querySelector('#settings-form').onsubmit=saveControlSettings;document.querySelector('#settings-close').onclick=closeSettings;document.querySelector('#settings-dialog').addEventListener('cancel',e=>{e.preventDefault();closeSettings()});document.querySelector('#hit-volume').oninput=e=>document.querySelector('#hit-volume-value').textContent=e.target.value+'%';document.querySelector('#music-volume').oninput=e=>document.querySelector('#music-volume-value').textContent=e.target.value+'%';document.querySelector('#timing-offset').oninput=e=>document.querySelector('#timing-offset-value').textContent=(Number(e.target.value)>0?'+':'')+e.target.value+' ms';document.querySelector('#settings-reset').onclick=()=>{stopEffectPreview();selectJudgmentStyle('filled');document.querySelector('#show-arrival-hints').checked=true;document.querySelector('#show-keyboard-labels').checked=true;draftSymbolSounds=defaultSymbolSounds();renderSymbolSounds();document.querySelector('#effect-pack').value='rhythm';updateEffectDescription();draftBindings=[...DEFAULT_BINDINGS];captureLane=null;document.querySelector('#hit-sound-enabled').checked=true;document.querySelector('#timing-offset').value=0;document.querySelector('#timing-offset-value').textContent='0 ms';document.querySelector('#music-volume').value=50;document.querySelector('#music-volume-value').textContent='50%';document.querySelector('#hit-volume').value=80;document.querySelector('#hit-volume-value').textContent='80%';renderBindingWheel();document.querySelector('#binding-status').textContent='已恢復預設，按儲存套用。'}}
